import{_ as t,a,o as r,a2 as s}from"./chunks/framework.DCcmcJcL.js";const g=JSON.parse('{"title":"Scheduled Tasks","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/scheduled-tasks.md","filePath":"getting-started/scheduled-tasks.md","lastUpdated":1789441803000}'),o={name:"getting-started/scheduled-tasks.md"};function n(d,e,h,i,u,l){return r(),a("div",null,e[0]||(e[0]=[s('<h1 id="scheduled-tasks" tabindex="-1">Scheduled Tasks <a class="header-anchor" href="#scheduled-tasks" aria-label="Permalink to &quot;Scheduled Tasks&quot;">​</a></h1><p>Some of your store&#39;s work happens on a timetable or in the background, not at the moment you click a button. Catalog rule prices are refreshed every night, campaigns go out once a day, and emails can wait in a queue before they&#39;re sent. For this to work, the server your store runs on needs two things set up.</p><p>You don&#39;t set these up in the admin panel. Ask your developer or hosting provider to check both when the store goes live.</p><h2 id="what-your-server-needs" tabindex="-1">What your server needs <a class="header-anchor" href="#what-your-server-needs" aria-label="Permalink to &quot;What your server needs&quot;">​</a></h2><ul><li><strong>The scheduler.</strong> The server runs Bagisto&#39;s scheduler every minute, and the scheduler starts each task below at its time.</li><li><strong>A queue worker, if the store uses a queue.</strong> A store can hand slow work, such as sending emails, to a background queue so pages stay fast. When it does, a queue worker must keep running to process that work. When the store doesn&#39;t use a queue, this work happens straight away and no worker is needed.</li></ul><h2 id="tasks-that-run-on-a-timetable" tabindex="-1">Tasks that run on a timetable <a class="header-anchor" href="#tasks-that-run-on-a-timetable" aria-label="Permalink to &quot;Tasks that run on a timetable&quot;">​</a></h2><table tabindex="0"><thead><tr><th>What happens</th><th>When</th><th>Page</th></tr></thead><tbody><tr><td>Catalog rule prices are recalculated, so rules start and stop on the right days</td><td>Every night, just after midnight</td><td><a href="./../marketing/catalog-rules.html">Catalog Rules</a></td></tr><tr><td>Product prices used for sorting and filtering are refreshed</td><td>Every night, just after midnight</td><td><a href="./../marketing/catalog-rules.html">Catalog Rules</a></td></tr><tr><td>Campaigns whose event date has arrived are sent</td><td>Once a day, at midnight</td><td><a href="./../marketing/campaigns.html">Campaigns</a></td></tr><tr><td>Reminder emails go out for overdue invoices</td><td>Once a day, at 3:00</td><td><a href="./../configure/invoice-settings.html">Invoice Settings</a></td></tr><tr><td>Product prices are recorded for the lowest-price disclosure, and old records are cleared</td><td>Every 15 minutes, and a clean-up once a day</td><td><a href="./../configure/omnibus.html">Omnibus Price Disclosure</a></td></tr><tr><td>Exchange rates are updated from your rates provider</td><td>Only when <strong>Scheduled Import</strong> is switched on, daily, weekly or monthly at the time you choose</td><td><a href="./../configure/exchange-rates-configurations.html">Exchange Rates</a></td></tr></tbody></table><p>Times follow your store&#39;s time zone.</p><h2 id="work-that-goes-through-the-queue" tabindex="-1">Work that goes through the queue <a class="header-anchor" href="#work-that-goes-through-the-queue" aria-label="Permalink to &quot;Work that goes through the queue&quot;">​</a></h2><p>When your store uses a queue, these wait for the queue worker:</p><ul><li>every email the store sends, including order, invoice, customer and campaign emails;</li><li>updating the prices and stock that catalog rules and the storefront use after you save a product or a rule;</li><li>indexing products for an external search engine such as Elasticsearch. See <a href="./../configure/search-engines.html">Search Engines</a>;</li><li>recording what shoppers search for. See <a href="./../marketing/search-terms.html">Search Terms</a>;</li><li>running imports. See <a href="./../settings/data-transfer.html">Data Transfer</a>;</li><li>building sitemap files. See <a href="./../marketing/sitemaps.html">Sitemaps</a>;</li><li>sending guests the link to their EU withdrawal request. See <a href="./../orders/eu-withdrawal.html">EU Withdrawal</a>.</li></ul><h2 id="signs-that-something-isn-t-running" tabindex="-1">Signs that something isn&#39;t running <a class="header-anchor" href="#signs-that-something-isn-t-running" aria-label="Permalink to &quot;Signs that something isn&#39;t running&quot;">​</a></h2><table tabindex="0"><thead><tr><th>What you notice</th><th>What&#39;s probably not running</th></tr></thead><tbody><tr><td>Emails arrive late or not at all</td><td>The queue worker</td></tr><tr><td>A catalog rule&#39;s discount doesn&#39;t appear or doesn&#39;t end on time</td><td>The scheduler</td></tr><tr><td>A campaign never goes out</td><td>The scheduler, and the queue worker if the store uses a queue</td></tr><tr><td>A sitemap file isn&#39;t created after you save it</td><td>The queue worker</td></tr><tr><td>An import stays at the same step</td><td>The queue worker</td></tr><tr><td>Exchange rates stay the same after their scheduled time</td><td>The scheduler</td></tr></tbody></table><p>If you notice any of these, ask your developer or hosting provider to check that the scheduler runs every minute and that the queue worker is running.</p>',14)]))}const m=t(o,[["render",n]]);export{g as __pageData,m as default};
